import { Badge } from "@/components/ui/badge"
import { LinkButton } from "@/components/ui/button"
import { Card, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { SemanticContent } from "@/components/ui/semantic-content"

type CardRecord = {
  title: string
  description?: string
  meta?: string
  href?: string
  badge?: { label: string }
  image?: { src: string; alt: string }
}

type State = { label: string; description?: string }

/**
 * Card collection: an optional section header over a grid or list of the
 * pinned Card, each with optional image, badge, meta and link. layout.grid |
 * layout.list are the closed members; loading, empty and error are states.
 */
export default function Cards({
  layout = "grid",
  header = { heading: "Featured work" },
  records = [
    { title: "Design system", description: "Tokens, components and sections in one library.", meta: "Guide", href: "#" },
    { title: "Publishing", description: "Assemble pages from frames and sections.", meta: "Guide", href: "#" },
    { title: "Copy", description: "Every string resolved per locale.", meta: "Guide", href: "#" },
  ],
  state,
  states = {
    loading: { label: "Loading" },
    empty: { label: "Nothing here yet" },
    error: { label: "Something went wrong" },
  },
}: {
  layout?: "grid" | "list"
  header?: { eyebrow?: string; heading?: string; description?: string }
  records?: CardRecord[]
  state?: "loading" | "empty" | "error"
  states?: Record<"loading" | "empty" | "error", State>
}) {
  const shown = state ?? (records.length === 0 ? "empty" : undefined)
  return (
    <section data-slot="cards" data-layout={layout} className="py-16">
      <div className="mx-auto flex max-w-6xl flex-col gap-8 px-6">
        {(header.heading || header.eyebrow || header.description) && (
          <header data-slot="section-header" className="flex max-w-3xl flex-col items-start gap-3">
            {header.eyebrow && <Badge variant="secondary">{header.eyebrow}</Badge>}
            {header.heading && <h2 className="font-heading text-3xl font-semibold tracking-tight text-balance">{header.heading}</h2>}
            {header.description && <SemanticContent as="p" className="text-muted-foreground">{header.description}</SemanticContent>}
          </header>
        )}
        {shown ? (
          <div
            role={shown === "error" ? "alert" : "status"}
            aria-busy={shown === "loading" || undefined}
            data-state={shown}
            className="rounded-xl border border-dashed border-border p-10 text-center"
          >
            <SemanticContent as="p" className="font-medium text-foreground">{states[shown].label}</SemanticContent>
            {states[shown].description && <SemanticContent as="small">{states[shown].description}</SemanticContent>}
          </div>
        ) : (
          <ul className={layout === "grid" ? "grid gap-4 sm:grid-cols-2 lg:grid-cols-3" : "flex flex-col gap-4"}>
            {records.map((r) => (
              <li key={r.title} className="flex">
                <Card className={layout === "list" ? "w-full sm:flex-row sm:items-center" : "w-full"}>
                  {r.image && (
                    <img
                      src={r.image.src}
                      alt={r.image.alt}
                      className={layout === "list" ? "aspect-video w-full object-cover sm:w-48" : "aspect-video w-full object-cover"}
                    />
                  )}
                  <CardHeader className="flex-1">
                    {(r.badge || r.meta) && (
                      <div className="flex items-center gap-2">
                        {r.badge && <Badge variant="outline">{r.badge.label}</Badge>}
                        {r.meta && <SemanticContent as="small">{r.meta}</SemanticContent>}
                      </div>
                    )}
                    <CardTitle>
                      {r.href ? (
                        <LinkButton href={r.href} variant="link" className="h-auto p-0 text-base font-medium text-foreground">
                          {r.title}
                        </LinkButton>
                      ) : (
                        r.title
                      )}
                    </CardTitle>
                    {r.description && <CardDescription>{r.description}</CardDescription>}
                  </CardHeader>
                </Card>
              </li>
            ))}
          </ul>
        )}
      </div>
    </section>
  )
}
